{
  "id": "V060",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "휴직 신청에 관한 반복 문의를 응대하려는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "규정에 근거해 조건과 서류를 설명하고 답을 확정하기 어려운 문의를 담당자에게 전달함."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건과 제출 서류가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "직원의 질문과 현재 게시된 사내 규정이 입력으로 제시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "조건·서류 설명 및 담당자에게 넘길 문의가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "규정으로 답을 확정하기 어려울 때 전달하며, 승인과 인사시스템 정보 변경은 제외함."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능 추가를 확인할 수 없음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "직원 질문, 응대 기능, 인사 담당자 전달의 역할 구분이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "답을 확정하기 어려운 문의를 인사 담당자에게 전달한다는 의미이며, 승인이나 정보 변경을 수행한다는 뜻은 아니다."
}
